window.ScripturaLexicons.DGP.entriesHtml += "<article id=\"entry-dgp-8401\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γραμματίδιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 487 na letra γ · nº geral 8401</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pequeno escrito (carta, livro de contas etc). 〈γραμματεῖον〉</p></section></article>\n<article id=\"entry-dgp-8402\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γραμματικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 488 na letra γ · nº geral 8402</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 aquele que conhece as letras; erudito; sábio ♦ ὁ γραμματικός 2 quem ensina a ler e a escrever 3 quem se ocupa de textos literários; gramático; crítico ♦ ἡ γραμματική 4 arte ou técnica das letras; gramática; alfabeto ♦ τὰ γραμματικά 5 conhecimentos gramaticais; estudo da gramática; gramática. 〈γράμμα〉</p></section></article>\n<article id=\"entry-dgp-8403\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γραμματικῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 489 na letra γ · nº geral 8403</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. como homem que sabe ler e escrever; como pessoa instruída.</p></section></article>\n<article id=\"entry-dgp-8404\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γραμμάτιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 490 na letra γ · nº geral 8404</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dim. de γράμμα.</p></section></article>\n<article id=\"entry-dgp-8405\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γραμματιστής, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 491 na letra γ · nº geral 8405</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 escriba; secretário; escrivão 2 quem ensina as primeiras letras; mestre-escola. 〈γράμμα〉</p></section></article>\n<article id=\"entry-dgp-8406\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γραμματοδιδασκαλεῖον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 492 na letra γ · nº geral 8406</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">escola onde se apren­dem as primeiras letras; escola elementar. 〈γραμμα­­­τοδιδάσκαλος〉</p></section></article>\n<article id=\"entry-dgp-8407\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γραμματοδιδάσκαλος, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 493 na letra γ · nº geral 8407</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">mestre das primeiras letras; mestre-escola. 〈γράμμα, διδάσκαλος〉</p></section></article>\n<article id=\"entry-dgp-8408\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γραμματοκύφων, ωνος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 494 na letra γ · nº geral 8408</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aquele que se curva sobre as letras; escriba. 〈κύπτω〉</p></section></article>\n<article id=\"entry-dgp-8409\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γραμματοφόρος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 495 na letra γ · nº geral 8409</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aquele que leva cartas; mensageiro; carteiro. 〈φέρω〉</p></section></article>\n<article id=\"entry-dgp-8410\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γραμματοφυλακεῖον</h1><div class=\"entry-meta\"><span>DGP · ordem 496 na letra γ · nº geral 8410</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e γραμματοφυλάκιον, ου (τό) depósito de arquivos; arquivo. 〈γράμμα, φύλαξ〉</p></section></article>\n<article id=\"entry-dgp-8411\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γραμμή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 497 na letra γ · nº geral 8411</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 Geom. figura de uma só dimensão; linha; reta; circunferência 2 traço de pincel ou de estilete; traço de pluma; contorno; traço de desenho 3 linha de partida ou de chegada; raia; limite 4 linha de um tabuleiro de jogos 5 Astron. pl. linhas imaginárias que unem os astros. 〈γράφω〉</p></section></article>\n<article id=\"entry-dgp-8412\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γραμμικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 498 na letra γ · nº geral 8412</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 linear; geométrico 2 hábil para traçar linhas. 〈γραμμή〉</p></section></article>\n<article id=\"entry-dgp-8413\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γραπτέος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 499 na letra γ · nº geral 8413</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de γράφω.</p></section></article>\n<article id=\"entry-dgp-8414\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γραπτός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 500 na letra γ · nº geral 8414</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 desenhado ou pintado em traços 2 marcado por traços 3 escrito. 〈γράφω〉</p></section></article>\n<article id=\"entry-dgp-8415\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γραπτύς, ύος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 501 na letra γ · nº geral 8415</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">arranhadura; esfoladura. 〈γράφω〉</p></section></article>\n<article id=\"entry-dgp-8416\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γράσος</h1><div class=\"entry-meta\"><span>DGP · ordem 502 na letra γ · nº geral 8416</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e γράσσος, ου (ὁ) bodum; fedor.</p></section></article>\n<article id=\"entry-dgp-8417\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γραῦς, γραός (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 503 na letra γ · nº geral 8417</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 mulher velha 2 nata de leite 3 ca­ranguejo do mar.</p></section></article>\n<article id=\"entry-dgp-8418\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γραφεῖον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 504 na letra γ · nº geral 8418</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cinzel para gravar 2 estilete para es­crever; lápis 3 pincel 4 escritura 5 escrito; livro 6 re­gistro; arquivo. 〈γράφω〉</p></section></article>\n<article id=\"entry-dgp-8419\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γραφεύς, έως (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 505 na letra γ · nº geral 8419</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 gravador; pintor 2 escriba; secre­tário; escrivão 3 escritor. 〈γράφω〉</p></section></article>\n<article id=\"entry-dgp-8420\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γραφή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 506 na letra γ · nº geral 8420</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 representação por linhas; desenho; representação; pintura 2 ação de escrever; escritura 3 aquilo que é representado; desenho; quadro 4 escrito (documento; catálogo; tratado; prescrição; receita); letra 5 ato público de acusação; ação penal: καί μοι λέγε τὴν γραφὴν ταύτην λαβών dem. toma e lê para mim esta acusação 6 ação de bordar; bordadura 7 ação de se pintar; pintura para o rosto. 〈γράφω〉</p></section></article>\n<article id=\"entry-dgp-8421\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γραφικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 507 na letra γ · nº geral 8421</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 hábil em pintar, desenhar ou escrever 2 adequado para escrever (cana, pena, tinta) 3 relativo à escritura: ἁμάρτημα γραφικόν erro de ortografia 4 hábil em descrever 5 susceptível de boa descrição 6 bem pintado; bem descrito ♦ ἡ γραφική [τέχνη] 7 a arte de pintar ou de escrever. 〈γράφω〉</p></section></article>\n<article id=\"entry-dgp-8422\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γραφικῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 508 na letra γ · nº geral 8422</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 como pintor; de forma expressiva; de modo pitoresco 2 em pintura; como nos quadros.</p></section></article>\n<article id=\"entry-dgp-8423\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γραφίς, ίδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 509 na letra γ · nº geral 8423</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 estilete; buril 2 agulha para bordar 3 o que está grafado; pintura; quadro; bordado. 〈γράφω〉</p></section></article>\n<article id=\"entry-dgp-8424\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γράφω</h1><div class=\"entry-meta\"><span>DGP · ordem 510 na letra γ · nº geral 8424</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἔγραφον; fut. γράψω, aor. ἔγραψα, perf. γέγραφα, m.-q.-perf. ἐγεγράφειν; pas. fut.2 γραφήσομαι, aor.2 ἐγράφην, perf. γέγραμμαι, m.-q.-perf. ἐγεγράμμην, fut. perf. γεγράψομαι) 1 rasgar; esfolar: γράψεν δέ οἱ ὀστέον ἀχρὶς αἰχμὴ Πολυδάμαντος hom. a ponta da lança de Polidamas rasgou-o até o osso 2 gravar; inscrever; escrever: ταῦτα ἔγραψαν ἐς στήλην lic. essas coisas gravaram na estela 3 desenhar; pintar: ἄλλοι εἰσὶ ζωγράφοι γράφοντες ἄλλα πολλὰ ζῷα plat. há outros pintores que pintam muitos outros seres animados 4 escrever; redigir; compor: τοιαῦτα μὲν δεῖν σοι γράφειν ᾤμην ésqn. julgava ser preciso escrever-te essas coisas 5 inscrever; registrar: ἐμὲ οὖν γράφε τῶν ἱππεύειν ὑπερεπιθυμούντων xen. inscreve-me, pois, entre os que desejam servir na cavalaria 6 propor por escrito (decreto, moção): ἔγραψεν ἐξιέναι βοηθήσοντας Ἀθηναίους din. propôs que os Atenienses partissem para socorrê-los ♦ méd. 7 gravar ou escrever para uso pessoal; consignar para si por escrito; anotar para si: γενομένου τέρατος φυλάσσουσι γραφόμενοι τἀποβαῖνον her. tendo acontecido um prodígio guardam por escrito o ocorrido 8 mandar copiar para si; mandar pintar: ταῦτα γραψάμενος ἀνέθηκε ἐς τὸ Ἡραῖον her. tendo mandado pintar essas coisas, consagrou o quadro no templo de Hera 9 redigir ou compor para si: ἀλλ᾽ ἐγραψάμην μὲν τότ᾽ εὐθὺς οἴκαδ᾽ ἐλθὼν ὑπομνήματα plat. mas logo que cheguei em casa anotei as lembranças 10 inscrever para si mesmo: ἕνα τῶν μαθητῶν καὶ ἐμὲ γράφου plat. inscreve-me também como um dos teus discípulos 11 propor por escrito uma ação na justiça contra alguém, ac.: τίνα γραφήν σε γέγραπται; plat. que ação propôs contra ti? γράφομαί σε παραδοσίας plut. eu te acuso de traição ♦ pas. 12 ser objeto de ação judiciária; ser acionado na justiça: ἐγράφη παρανόμων τὸ ψήφισμα ésqn. o decreto foi acusado de ilegalidade, ἡ γραφεῖσα δίκη dem. o processo intentado, τὸ γεγραμμένον dem. a questão em litígio.</p></section></article>\n<article id=\"entry-dgp-8425\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γραώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 511 na letra γ · nº geral 8425</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. próprio de mulher idosa. 〈γραῦς〉</p></section></article>\n<article id=\"entry-dgp-8426\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γρηγορέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 512 na letra γ · nº geral 8426</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres. e aor.) 1 estar ou manter-se desperto 2 manter-se em vigilância; estar atento em algo, ἐπί e dat. 〈ἐγρήγορα, de ἐγείρω〉</p></section></article>\n<article id=\"entry-dgp-8427\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γρηύς</h1><div class=\"entry-meta\"><span>DGP · ordem 513 na letra γ · nº geral 8427</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e γρῆϋς jôn. = γραῦς.</p></section></article>\n<article id=\"entry-dgp-8428\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γρῖφος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 514 na letra γ · nº geral 8428</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 rede de junco; rede de pesca; armadilha 2 emaranhado de palavras; enigma.</p></section></article>\n<article id=\"entry-dgp-8429\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γριφώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 515 na letra γ · nº geral 8429</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">enigmático; obscuro. 〈γρῖφος〉</p></section></article>\n<article id=\"entry-dgp-8430\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γρῦ</h1><div class=\"entry-meta\"><span>DGP · ordem 516 na letra γ · nº geral 8430</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">coisa insignificante: οὐδὲ γρῦ nada de nada, οὐδὲ γρῦ λέγειν não dizer nenhuma palavra; não dar um pio.</p></section></article>\n<article id=\"entry-dgp-8431\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γρύζω</h1><div class=\"entry-meta\"><span>DGP · ordem 517 na letra γ · nº geral 8431</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. γρύξομαι, aor. ἔγρυξα, perf. desus.) 1 (porco) grunhir 2 soltar gritos terríveis; murmurar; resmungar.</p></section></article>\n<article id=\"entry-dgp-8432\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γρυλίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 518 na letra γ · nº geral 8432</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e γρυλλίζω = γρύζω.</p></section></article>\n<article id=\"entry-dgp-8433\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γρυμέα</h1><div class=\"entry-meta\"><span>DGP · ordem 519 na letra γ · nº geral 8433</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e γρυμεία, ας (ἡ) 1 saco ou cesto para guardar roupas velhas 2 roupa ou móvel usado 3 choldra; gentalha; ralé.</p></section></article>\n<article id=\"entry-dgp-8434\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γρυμεοπώλης</h1><div class=\"entry-meta\"><span>DGP · ordem 520 na letra γ · nº geral 8434</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e γρυμαιοπώλης, ου (ὁ) mercador de velharias (roupas, móveis). 〈γρυμέα, πωλέομαι〉</p></section></article>\n<article id=\"entry-dgp-8435\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γρυπός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 521 na letra γ · nº geral 8435</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de nariz adunco; de nariz aquilino 2 adunco; arredondado; curvo.</p></section></article>\n<article id=\"entry-dgp-8436\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γρυπότης, ητος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 522 na letra γ · nº geral 8436</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 aduncidade nasal 2 curvatura. 〈γρυπός〉</p></section></article>\n<article id=\"entry-dgp-8437\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γρύψ, γρυπός (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 523 na letra γ · nº geral 8437</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 grifo, ave de rapina 2 âncora. 〈γρυπός〉</p></section></article>\n<article id=\"entry-dgp-8438\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γύαλον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 524 na letra γ · nº geral 8438</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 parte convexa de uma couraça 2 cavidade; profundidade de um recipiente; vaso fundo 3 cavidade de rochedos; vale; antro; profundezas: γύαλα Παρνησοῖο hes. os profundos vales do Parnaso, αἰθέρια γύαλα opp. a profundidade do céu.</p></section></article>\n<article id=\"entry-dgp-8439\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Γυγάδας1, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 525 na letra γ · nº geral 8439</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">o tesouro de Giges, em Delfos. 〈Γύγης〉</p></section></article>\n<article id=\"entry-dgp-8440\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Γυγάδας2, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 526 na letra γ · nº geral 8440</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) consagrado por Giges. 〈Γύγης〉</p></section></article>\n<article id=\"entry-dgp-8441\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Γυγαίη, ης</h1><div class=\"entry-meta\"><span>DGP · ordem 527 na letra γ · nº geral 8441</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) 1 [λίμνη] o lago de Giges ♦ ἡ Γυγαίη 2 Gigeia, n. de mulher.</p></section></article>\n<article id=\"entry-dgp-8442\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Γύγης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 528 na letra γ · nº geral 8442</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Giges, rei da Lídia.</p></section></article>\n<article id=\"entry-dgp-8443\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γύης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 529 na letra γ · nº geral 8443</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 eixo da charrua, peça de madeira recurva à qual está ligada a relha do arado 2 medida agrária 3 campo fértil 4 ὁ Γύης, Gias ou Gies, um dos Gigantes de cem braços.</p></section></article>\n<article id=\"entry-dgp-8444\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γυιοβαρής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 530 na letra γ · nº geral 8444</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que entorpece os membros. 〈γυῖον, βάρος〉</p></section></article>\n<article id=\"entry-dgp-8445\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γυῖον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 531 na letra γ · nº geral 8445</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 membro humano 2 pl. extremidades: pernas; pés 3 mão; punho 4 pl. mãos; braços 5 regaço; entranhas; ventre 6 corpo.</p></section></article>\n<article id=\"entry-dgp-8446\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γυιοπέδης, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 532 na letra γ · nº geral 8446</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">entrave.</p></section></article>\n<article id=\"entry-dgp-8447\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γυιός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 533 na letra γ · nº geral 8447</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">coxo; estropiado; fraco.</p></section></article>\n<article id=\"entry-dgp-8448\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γυιόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 534 na letra γ · nº geral 8448</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tornar coxo; estropiar 2 ferir; enfraquecer. 〈γυιός〉</p></section></article>\n<article id=\"entry-dgp-8449\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γυμνάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 535 na letra γ · nº geral 8449</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. γυμνάσω, aor. ἐγύμνασα, perf. γεγύμνακα; pas. aor. ἐγυμνάσθην, perf. γεγύμνασμαι) 1 exercitar; treinar alguém, ac., em algo, dat. ou περί e ac.: οὓς ἐχρῆν τοὺ συνόντας περὶ τὴν ἐμπειρίαν τὴν τούτων γυμνάζειν isócr. os quais deviam exercitar seus companheiros na prática dessas coisas [da vida política], γυμνάσαι ἑαυτόν τε καὶ τοὺς ἵππους xen. exercitar a si próprio e também aos cavalos 2 fatigar; estafar: ἅδην με πολύπλαναι πλάναι γεγυμνάκασιν ésql. o longo vagar errante muito me fatigou ♦ méd.pas. 3 fazer exercício; exercitar-se; adestrar-se em algo, ac., πρός e ac., ἐν e dat.: γυμνάσασθαι ἱκανῶς τὴν τέχνην plat. ter-se exercitado convenientemente na arte, καλῶς φαίνῃ μοι γεγυμνάσθαι πρὸς τὸ διειδέναι τὰ Κρητῶν νόμιμα plat. a mim me pareces bem treinado em conhecer os costumes dos cretenses, τοὺς ἐν ἐκείνοις γεγυμνασμένους plat. os que estão treinados nisso 4 fatigar-se por algo, ac.: τοὺς ὑπερμήκεις δρόμους Ἥρᾳ στυγητὸς πρὸς βίαν γυμνάζεται; ésql. odiada por Hera, é submetida à força a fatigar-se em longas corridas? 〈γυμνός〉</p></section></article>\n<article id=\"entry-dgp-8450\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γυμνάς, άδος</h1><div class=\"entry-meta\"><span>DGP · ordem 536 na letra γ · nº geral 8450</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) 1 nu 2 exercitado; prepa­rado ♦ ὁ γυμνάς 3 atleta; ginasta ♦ ἡ γυμνάς 4 ginásio; palestra. 〈γυμνός〉</p></section></article>\n<article id=\"entry-dgp-8451\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γυμνασία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 537 na letra γ · nº geral 8451</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 prática do ginásio; exercício 2 pre­paro para a política. 〈γυμνάζω〉</p></section></article>\n<article id=\"entry-dgp-8452\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γυμνασιαρχέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 538 na letra γ · nº geral 8452</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ser ginasiarca; dirigir exercícios gi­násticos ♦ méd. 2 desempenhar a função de gina­siarca ♦ pas. 3 receber ginasiarcas; ter ginasiarcas. 〈γυμνασίαρχος〉</p></section></article>\n<article id=\"entry-dgp-8453\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γυμνασιαρχία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 539 na letra γ · nº geral 8453</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">condição ou cargo de ginasiarca. 〈γυμνασίαρχος〉</p></section></article>\n<article id=\"entry-dgp-8454\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γυμνασιαρχικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 540 na letra γ · nº geral 8454</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de ginasiarca ou relativo a ginasiarca. 〈γυμνασίαρχος〉</p></section></article>\n<article id=\"entry-dgp-8455\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γυμνασίαρχος, ου 〈ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 541 na letra γ · nº geral 8455</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ginasiarca 2 diretor de um ginásio. 〈γυμνάσιον〉</p></section></article>\n<article id=\"entry-dgp-8456\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γυμνάσιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 542 na letra γ · nº geral 8456</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 exercício físico 2 escola de gi­nástica; ginásio; palestra 3 escola 4 exercício; prova. 〈γυμνάζω〉</p></section></article>\n<article id=\"entry-dgp-8457\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γύμνασμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 543 na letra γ · nº geral 8457</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">exercício físico ou intelectual. 〈γυμνάζω〉</p></section></article>\n<article id=\"entry-dgp-8458\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γυμναστέον</h1><div class=\"entry-meta\"><span>DGP · ordem 544 na letra γ · nº geral 8458</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de γυμνάζω.</p></section></article>\n<article id=\"entry-dgp-8459\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γυμναστής, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 545 na letra γ · nº geral 8459</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 professor de ginástica 2 adestrador. 〈γυμνάζω〉</p></section></article>\n<article id=\"entry-dgp-8460\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γυμναστικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 546 na letra γ · nº geral 8460</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que concerne aos exercícios físicos 2 de atleta. 〈γυμνάζω〉</p></section></article>\n<article id=\"entry-dgp-8461\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γυμνής, ῆτος</h1><div class=\"entry-meta\"><span>DGP · ordem 547 na letra γ · nº geral 8461</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) 1 nu 2 munido de armas de infantaria ♦ ὁ γυμνής 3 soldado da infantaria. 〈γυμνός〉</p></section></article>\n<article id=\"entry-dgp-8462\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γυμνητεία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 548 na letra γ · nº geral 8462</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tropa da infantaria 2 nudez. 〈γυμνητεύω〉</p></section></article>\n<article id=\"entry-dgp-8463\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γυμνητεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 549 na letra γ · nº geral 8463</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres.) 1 estar armado para a infantaria 2 estar nu 3 ser despojado de, gen. 〈γυμνής〉</p></section></article>\n<article id=\"entry-dgp-8464\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γυμνήτης, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 550 na letra γ · nº geral 8464</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) 1 nu 2 desprovido do supérfluo; simples ♦ ὁ γυμνήτης 3 soldado armado da infantaria. 〈γυμνής〉</p></section></article>\n<article id=\"entry-dgp-8465\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γυμνητικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 551 na letra γ · nº geral 8465</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que concerne aos soldados da infantaria. 〈γυμνής〉</p></section></article>\n<article id=\"entry-dgp-8466\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γυμνῆτις, ιδος</h1><div class=\"entry-meta\"><span>DGP · ordem 552 na letra γ · nº geral 8466</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) própria dos gimnossofistas.</p></section></article>\n<article id=\"entry-dgp-8467\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γυμνικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 553 na letra γ · nº geral 8467</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">relativo a exercícios físicos. 〈γυμνός〉</p></section></article>\n<article id=\"entry-dgp-8468\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γυμνοπαιδία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 554 na letra γ · nº geral 8468</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Gimnopédios, em Esparta festa anual em que meninos e adultos dançavam nus. 〈γυμνός, παῖς〉</p></section></article>\n<article id=\"entry-dgp-8469\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γυμνός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 555 na letra γ · nº geral 8469</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 nu 2 desprovido de cobertura, de in­vólucro, de apetrechos, de guarnição: γ. ἵππος arr. cavalo sem arreios, γ. ξίφος a.r. punhal fora da bainha 3 desprovido de, gen.: ψυχὴ γυμνὴ τοῦ σώματος plat. alma despojada do corpo, γυμνὸς ὅπλων her. sem armas 4 escassamente vestido; sem manto e só com túnica 5 sem arma de defesa; sem escudo 6 tard. sem restrição nem modificação: γ. κόκκος n.t. puro e simples grão de areia ♦ τὰ γυμνά 7 partes do corpo não cobertas pela armadura, partic. o lado direito não coberto pelo escudo.</p></section></article>\n<article id=\"entry-dgp-8470\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Γυμνοσοφισταί, ῶν (οἱ)</h1><div class=\"entry-meta\"><span>DGP · ordem 556 na letra γ · nº geral 8470</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Gimnossofistas, sábios da Índia que viviam nus. 〈γυμνός, σοφιστής〉</p></section></article>\n<article id=\"entry-dgp-8471\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γυμνότης, ητος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 557 na letra γ · nº geral 8471</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. nudez. 〈γυμνός〉</p></section></article>\n<article id=\"entry-dgp-8472\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γυμνόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 558 na letra γ · nº geral 8472</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 desnudar; despir: γ. σῶμα sóf. desnudar um cadáver 2 despojar alguém ou algo, ac., de alguma coisa, gen.: γ. τὰ ὀστέα τῶν κρεῶν her. despojar das carnes os ossos 3 depor; pôr de lado: γ. σάκκον sept. despir o rude manto ♦ pas. 4 despojar-se; ser despojado de algo, gen.: γυμνωθὲν ξίφος her. espada nua; desembainhada, ἐπειδὰν [ἡ ψυχὴ] γυμνωθῆ τοῦ σώματος plat. quando a alma se despoja do corpo, τεῖχος ἐγυμνώθη hom. a muralha ficou desguarnecida. 〈γυμνός〉</p></section></article>\n<article id=\"entry-dgp-8473\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γύμνωσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 559 na letra γ · nº geral 8473</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 desnudamento 2 nudez 3 parte do corpo desnudada e não protegida por um escudo, partic. o lado direito. 〈γυμνόω〉</p></section></article>\n<article id=\"entry-dgp-8474\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γύναι</h1><div class=\"entry-meta\"><span>DGP · ordem 560 na letra γ · nº geral 8474</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. γυνή.</p></section></article>\n<article id=\"entry-dgp-8475\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γυναικάριον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 561 na letra γ · nº geral 8475</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. mulherzinha; mulher vulnerável. 〈γυνή〉</p></section></article>\n<article id=\"entry-dgp-8476\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γυναικεῖος, α</h1><div class=\"entry-meta\"><span>DGP · ordem 562 na letra γ · nº geral 8476</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ος, ον 1 de mulher; de mulheres; feminino 2 próprio de mulheres ♦ ἡ γυναικηΐη jôn. 3 aposento para mulheres; gineceu ♦ τὰ γυναικεῖα 4 vestes femininas 5 órgãos genitais femininos 6 menstruação. 〈γυνή〉</p></section></article>\n<article id=\"entry-dgp-8477\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γυναικήιος</h1><div class=\"entry-meta\"><span>DGP · ordem 563 na letra γ · nº geral 8477</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = γυναικεῖος.</p></section></article>\n<article id=\"entry-dgp-8478\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γναικίας, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 564 na letra γ · nº geral 8478</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">homem afeminado. 〈γυνή〉</p></section></article>\n<article id=\"entry-dgp-8479\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γυναικίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 565 na letra γ · nº geral 8479</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">comportar-se como mulher; agir como mulher. 〈γυνή〉</p></section></article>\n<article id=\"entry-dgp-8480\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γυναικισμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 566 na letra γ · nº geral 8480</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fraqueza de mulher; pusilanimidade. 〈γυναικίζω〉</p></section></article>\n<article id=\"entry-dgp-8481\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γυναικόβουλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 567 na letra γ · nº geral 8481</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">meditado por uma mulher. 〈γυνή, βουλή〉</p></section></article>\n<article id=\"entry-dgp-8482\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γυναικογήρυτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 568 na letra γ · nº geral 8482</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">proclamado por uma mulher. 〈γυνή, γηρύω〉</p></section></article>\n<article id=\"entry-dgp-8483\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γυναικοκρατέομαι-οῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 569 na letra γ · nº geral 8483</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só part. pres. pas. γυναικο­κρατεόμενος) governado por mulheres. 〈γυνή, κρατέω〉</p></section></article>\n<article id=\"entry-dgp-8484\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γυναικοκρατία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 570 na letra γ · nº geral 8484</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dominação de mulheres; soberania exercida por mulheres.</p></section></article>\n<article id=\"entry-dgp-8485\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γυναικομανής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 571 na letra γ · nº geral 8485</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">apaixonado por um mulheres. 〈γυνή, μαίνομαι〉</p></section></article>\n<article id=\"entry-dgp-8486\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γυναικόμιμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 572 na letra γ · nº geral 8486</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que imita as mulheres. 〈γυνή, μιμέομαι〉</p></section></article>\n<article id=\"entry-dgp-8487\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γυναικοπληθής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 573 na letra γ · nº geral 8487</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">composto por mulheres; que tem mulheres em grande número. 〈γυνή, πλῆθος〉</p></section></article>\n<article id=\"entry-dgp-8488\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γυναικόποινος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 574 na letra γ · nº geral 8488</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">vingador de mulheres. 〈γυνή, ποινή〉</p></section></article>\n<article id=\"entry-dgp-8489\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γυναικοπρεπής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 575 na letra γ · nº geral 8489</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que convém a uma mulher; feminino. 〈γυνή, πρέπω〉</p></section></article>\n<article id=\"entry-dgp-8490\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γυναικοφίλης, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 576 na letra γ · nº geral 8490</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) que ama as mulheres. 〈γυνή, φίλος〉</p></section></article>\n<article id=\"entry-dgp-8491\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γυναικώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 577 na letra γ · nº geral 8491</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">parecido com uma mulher; afemi­nado. 〈γυνή〉</p></section></article>\n<article id=\"entry-dgp-8492\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γυναικών, ῶνος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 578 na letra γ · nº geral 8492</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aposento de mulheres; gineceu. 〈γυνή〉</p></section></article>\n<article id=\"entry-dgp-8493\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γυναικωνῖτις, ιδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 579 na letra γ · nº geral 8493</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 aposento de mulheres; gineceu 2 espaço reservado às mulheres no templo judaico 3 população feminina 4 harém. 〈γυναικών〉</p></section></article>\n<article id=\"entry-dgp-8494\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γυναιμανής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 580 na letra γ · nº geral 8494</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">γυναικομανής.</p></section></article>\n<article id=\"entry-dgp-8495\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γύναιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 581 na letra γ · nº geral 8495</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">mulher pequena. 〈γυνή〉</p></section></article>\n<article id=\"entry-dgp-8496\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γύναιος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 582 na letra γ · nº geral 8496</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 concernente a mulher 2 feito para mulher (presente). 〈γυνή〉</p></section></article>\n<article id=\"entry-dgp-8497\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γυνή, γυναικός,</h1><div class=\"entry-meta\"><span>DGP · ordem 583 na letra γ · nº geral 8497</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">voc. γύναι (ἡ) 1 mulher 2 mulher; esposa ou concubina 3 fêmea de animal.</p></section></article>\n<article id=\"entry-dgp-8498\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γύννις, ιδος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 584 na letra γ · nº geral 8498</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">homem afeminado.</p></section></article>\n<article id=\"entry-dgp-8499\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γύπεσσι</h1><div class=\"entry-meta\"><span>DGP · ordem 585 na letra γ · nº geral 8499</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dat. pl. ép. de γύψ.</p></section></article>\n<article id=\"entry-dgp-8500\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γυπιάς, άδος</h1><div class=\"entry-meta\"><span>DGP · ordem 586 na letra γ · nº geral 8500</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) habitado por abutres. 〈γύψ〉</p></section></article>";
